// soy-milk-rank: soy milk ranks below short-list plant milks; fortified is no longer the pick; FDA facts and earlier lines stay; no health claims.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { nonEmpty } from '../../lib/testGuards.js';
import { matchItemToCard } from '../../lib/listMatch.js';
import doLines from '../../lib/doLines.json' with { type: 'json' };

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));
const ROOT = new URL('../../../', import.meta.url).pathname;
const pre = JSON.parse(execFileSync('git', ['show', 'f3ab9b4:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());
const card = (id) => { const e = kb.entries.find((x) => x.id === id); assert.ok(e, `${id} missing`); return e; };
const was = (id) => { const e = pre.entries.find((x) => x.id === id); assert.ok(e, `${id} missing before`); return e; };
const SKIP = new Set(['sources', 'aliases', 'asked_as', 'id', 'kind', 'category']);
const strings = (v) => (typeof v === 'string' ? [v] : Array.isArray(v) ? v.flatMap(strings) : v && typeof v === 'object' ? Object.values(v).flatMap(strings) : []);
const fields = (e) => Object.entries(e).filter(([k]) => !SKIP.has(k)).flatMap(([, v]) => strings(v));
// Text this batch adds or changes; lines already on the card before the batch are not this batch's claims.
const addedList = (id) => { const old = new Set(fields(was(id))); return fields(card(id)).filter((s) => !old.has(s)); };
const added = (id) => addedList(id).join(' \n ');
const words = (s) => String(s).trim().split(/\s+/).filter(Boolean).length;

const ID = 'soy_milk';
const soy = () => card(ID);
const tips = () => (soy().buying_tips || []);

test('C1 the decision and cart pick point to a short list, not fortified', () => {
  const { decision, cart_pick } = soy();
  assert.match(decision, /short list/i, 'names a short list');
  assert.match(decision, /soybeans and water/i, 'beyond soybeans and water');
  assert.match(decision, /unsweetened/i);
  assert.doesNotMatch(decision, /fortif/i, 'fortified is no longer the pick');
  assert.ok(words(decision) <= 10, `decision runs ${words(decision)} words`);
  assert.match(cart_pick, /unsweetened soy milk/i);
  assert.doesNotMatch(cart_pick, /fortif/i);
  assert.ok(cart_pick.length <= 46, `cart_pick is ${cart_pick.length} characters`);
  const m = matchItemToCard(cart_pick);
  assert.equal(m ? m.slug ?? m.id ?? m.entry?.id : null, ID, 'cart_pick resolves to the soy_milk card');
});

test('C2 a short-list almond milk ranks above soy milk, and dairy shoppers see the Milk card', () => {
  const t = tips().join(' \n ');
  assert.match(t, /almond[\s\S]*(ranks )?above[\s\S]*soy milk/i, 'almond milk ranks above soy milk');
  assert.match(t, /short[- ]list/i);
  assert.match(t, /dairy[\s\S]*\bMilk\b|\bMilk card\b/, 'dairy shoppers are pointed to the Milk card');
  assert.equal(kb.entries.find((e) => e.id === 'whole_vs_reduced_fat_milk').title, 'Milk', 'the pointed-to card is titled Milk');
});

test('C3 fortified is not the pick, fortification adds ingredients, and the FDA facts stay', () => {
  const t0 = tips()[0];
  assert.match(t0, /soybeans and water/i, 'tip 0 is the short-list tip');
  assert.doesNotMatch(t0, /fortif/i, 'tip 0 no longer leads with fortified');
  assert.ok(t0.length <= 90, `tip 0 is ${t0.length} characters`);
  assert.match(added(ID), /fortif[\s\S]*(ingredient|list)/i, 'a new line says fortifying adds ingredients');
  for (const f of ['why', 'short_answer', 'detail', 'science']) assert.equal(soy()[f], was(ID)[f], `${f} (the FDA dairy-group facts) changed`);
  assert.match(soy().why + soy().detail, /dairy group/i);
  for (const s of was(ID).buying_tips) assert.ok(tips().includes(s), `old tip lost: ${s}`);
});

test('C4 earlier batches stay; frozen fields and the sibling plant milks are untouched', () => {
  const a = soy(), b = was(ID);
  assert.deepEqual((a.watch_out || []).slice(0, b.watch_out.length), b.watch_out, 'watch_out lost or reordered a line');
  assert.ok(a.watch_out.length > b.watch_out.length, 'watch_out gained nothing');
  for (const re of [/carrageenan/i, /bioengineered/i, /Non-GMO Project Verified/]) assert.match([...a.buying_tips, ...a.watch_out].join(' '), re);
  assert.deepEqual(a.sources, b.sources, 'sources changed');
  for (const f of ['tier_note', 'why', 'short_answer', 'detail', 'science', 'labels_decoded', 'instead', 'aliases', 'asked_as', 'question', 'title', 'evidence_tier', 'category']) assert.deepEqual(a[f], b[f], `${f} changed`);
  assert.equal(a.pick_steps[1], b.pick_steps[1], 'pick_steps[1] changed');
  assert.deepEqual(card('coconut_milk_beverage'), was('coconut_milk_beverage'), 'coconut_milk_beverage changed');
  for (const id of nonEmpty(['almond_milk', 'oat_milk'], 'sibling plant milks', 2)) assert.deepEqual({ ...card(id), instead: 0 }, { ...was(id), instead: 0 }, `${id} changed beyond instead`);
});

test('C7 sibling instead lines point to another short-list plant milk', () => {
  const want = { almond_milk: /oat milk/i, oat_milk: /almond milk/i };
  for (const [id, re] of Object.entries(want)) {
    const { instead, cart_pick } = card(id);
    assert.match(instead, /short[- ]list/i, `${id} instead names a short list`);
    assert.match(instead, re, `${id} instead names the other plant milk`);
    assert.doesNotMatch(instead, /soy|fortif/i, `${id} instead no longer names fortified soy`);
    assert.ok(words(instead) <= 24 && instead !== cart_pick, `${id} instead length or equals cart_pick`);
    assert.doesNotMatch(added(id), /testosterone|estrogen|hormon|—|\b(I|me|my)\b/i);
  }
  for (const e of nonEmpty(kb.entries, 'kb entries', 100)) assert.doesNotMatch(String(e.instead ?? ''), /fortified unsweetened soy milk is the next/i, `${e.id} still names fortified soy as the next plant drink`);
});

test('C5 new lines are readable: at most 20 words a sentence, at most one semicolon', () => {
  const lines = nonEmpty(addedList(ID), 'soy_milk added lines', 4);
  for (const l of lines) {
    for (const s of l.split(/(?<=[.!?])\s+/)) {
      assert.ok(s.split(/\s+/).length <= 20, `sentence over 20 words: ${s}`);
      assert.ok((s.match(/;/g) || []).length <= 1, `stacked semicolons: ${s}`);
    }
  }
});

test('C6 no hormone, health, first person, em dash, price, calorie or brand wording; the do line mirrors the headline', () => {
  const t = nonEmpty([added(ID), String(doLines[ID] ?? '')], 'added text', 2).join(' \n ');
  assert.doesNotMatch(t, /testosterone|estrogen|hormon|phyto|male|men's/i, 'hormone or bodily-effect wording');
  assert.doesNotMatch(t, /\b(causes?|prevents?|treats?|cures?|lowers? (the )?risk|cancer|toxic\w*|unsafe|safe|safer|harm\w*|risks?|linked to|health\w*|neurolog\w*|immun\w*|exposure|doses?|allerg\w*|estro\w*)\b/i, 'health or treatment wording');
  assert.doesNotMatch(t, /\b(I|me|my)\b/, 'first person');
  assert.doesNotMatch(t, /—/, 'em dash');
  assert.doesNotMatch(t, /\$\s?\d|\bprice\w*|\bcheap\w*|\bcalor\w*|\blogged\b/i, 'price or calorie wording');
  assert.doesNotMatch(t, /\b(Silk|Oatly|Califia|Pacific|Westsoy|Edensoy|Whole Foods|Costco|Kroger|Trader Joe)\b/i, 'brand name');
  assert.match(doLines[ID], /soybeans and water/i, 'the do line mirrors the new headline');
  assert.doesNotMatch(String(doLines[ID]), /fortif/i);
  assert.match(readFileSync(new URL('../../../docs/do-lines-review.md', import.meta.url), 'utf8'), /\| `soy_milk` \| eggs_dairy \| Unsweetened soy milk, a short list beyond soybeans and water\. \|/, 'review table row carries the new headline');
});
// concern-bioengineered: the GMO-crop cards name what a bioengineered label means and omits, and the organic > Non-GMO Project Verified ladder; earlier lines stay; no health claims; sources from the archive.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { nonEmpty } from '../../lib/testGuards.js';

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));
const ROOT = new URL('../../../', import.meta.url).pathname;
const pre = JSON.parse(execFileSync('git', ['show', 'c24aea0:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());
const card = (id) => { const e = kb.entries.find((x) => x.id === id); assert.ok(e, `${id} missing`); return e; };
const was = (id) => { const e = pre.entries.find((x) => x.id === id); assert.ok(e, `${id} missing before`); return e; };
const SKIP = new Set(['sources', 'aliases', 'asked_as', 'id', 'kind', 'category']);
const strings = (v) => (typeof v === 'string' ? [v] : Array.isArray(v) ? v.flatMap(strings) : v && typeof v === 'object' ? Object.values(v).flatMap(strings) : []);
const fields = (e) => Object.entries(e).filter(([k]) => !SKIP.has(k)).flatMap(([, v]) => strings(v));
// Text this batch adds; lines already on the card before the batch are not this batch's claims.
const addedList = (id) => { const old = new Set(fields(was(id))); return fields(card(id)).filter((s) => !old.has(s)); };
const added = (id) => addedList(id).join(' \n ');
const urlsOf = (e) => (e.sources || []).map((s) => (typeof s === 'string' ? (s.match(/https?:\S+/) || [])[0] : s.url)).filter(Boolean);
const tipsOf = (id) => (card(id).buying_tips || []).join(' \n ');
const outsOf = (id) => (card(id).watch_out || []).join(' \n ');

const HOME = 'label_nonGMO_vs_organic';
const CROP = { cooking_oils: /canola/i, sugars: /sugar beets?/i, soy_milk: /soybeans?/i, tortilla_chips: /\bcorn\b/i, tortillas: /\bcorn\b/i };
const LADDER = /organic[\s\S]*Non-GMO Project Verified/;
const TARGETS = [HOME, 'cooking_oils', 'sugars', 'soy_milk', 'tortilla_chips', 'tortillas', 'popcorn'];
const CSPI = 'https://www.cspi.org/article/what-know-about-new-gmo-disclosures';
const NGP = 'https://www.nongmoproject.org/gmo-faq/';

const root = join(ROOT, 'docs/sources/concerns');
const archived = new Set();
for (const d of readdirSync(root, { withFileTypes: true }).filter((x) => x.isDirectory())) {
  for (const f of readdirSync(join(root, d.name)).filter((x) => x.endsWith('.md'))) {
    const m = readFileSync(join(root, d.name, f), 'utf8').match(/^url:\s*(\S+)/m);
    if (m) archived.add(m[1]);
  }
}

test('C1 the home card names the package word, the voluntary derived line, the QR or phone route, the exemptions, the unapproved claims and the ladder', () => {
  const tips = tipsOf(HOME), outs = outsOf(HOME);
  assert.match(tips, /bioengineered/i, 'the package word');
  assert.match(tips + outs, /QR code|phone number/i, 'disclosure by QR code or phone');
  assert.match(outs, /derived from bioengineering/i, 'the derived-from line');
  assert.match(outs, /voluntary/i, 'derived line is voluntary');
  assert.match(outs, /restaurants?/i);
  assert.match(outs, /very small/i);
  assert.match(outs, /government[^.]*(not|n't)[^.]*approve|not (government[- ])?approved/i, 'non-GMO claims not government-approved');
  assert.match(outs, /soybeans[\s\S]*corn[\s\S]*sugar beets[\s\S]*canola|canola[\s\S]*sugar beets/i, 'which crops');
  assert.match(tips, LADDER, 'ladder organic > Non-GMO Project Verified');
});

test('C2 each other target card names its crop and the ladder; popcorn says never', () => {
  for (const [id, re] of Object.entries(CROP)) {
    const t = addedList(id).join(' \n ');
    assert.match(t, /bioengineer/i, `${id} names bioengineered`);
    assert.match(t, re, `${id} names its crop`);
    assert.match(tipsOf(id), LADDER, `${id} ladder organic > Non-GMO Project Verified`);
  }
  const p = added('popcorn');
  assert.match(p, /bioengineer/i, 'popcorn names bioengineered');
  assert.match(p, /never/i, 'popcorn is never bioengineered');
  assert.match(p, /CSPI/, 'popcorn attributes CSPI');
  assert.match(outsOf('popcorn'), /derived from bioengineering/i, 'bag oil is derived');
});

test('C3 earlier lines stay and frozen fields are untouched on every target', () => {
  for (const id of nonEmpty(TARGETS, 'targets', 7)) {
    const a = card(id), b = was(id);
    for (const f of ['buying_tips', 'watch_out']) {
      const old = b[f] || [];
      assert.deepEqual((a[f] || []).slice(0, old.length), old, `${id} ${f} lost or reordered a line`);
      assert.ok((a[f] || []).length > old.length, `${id} ${f} gained nothing`);
    }
    for (const f of ['decision', 'cart_pick', 'tier_note', 'why', 'short_answer', 'detail', 'science', 'labels_decoded', 'pick_steps', 'kristy_take', 'instead', 'aliases', 'asked_as', 'question', 'title']) assert.deepEqual(a[f], b[f], `${id} ${f} changed`);
    assert.equal((a.buying_tips || [])[0], (b.buying_tips || [])[0], `${id} tip0 changed`);
  }
});

test('C4 new lines are readable: at most 20 words a sentence, at most one semicolon', () => {
  for (const id of TARGETS) {
    const lines = nonEmpty(addedList(id), `${id} added lines`, 2);
    for (const l of lines) {
      for (const s of l.split(/(?<=[.!?])\s+/)) {
        assert.ok(s.split(/\s+/).length <= 20, `${id} sentence over 20 words: ${s}`);
        assert.ok((s.match(/;/g) || []).length <= 1, `${id} stacked semicolons: ${s}`);
      }
    }
  }
});

test('C5 sources come from the concern archive and nothing is dropped', () => {
  nonEmpty([...archived], 'archived urls', 100);
  for (const u of [CSPI, NGP]) assert.ok(archived.has(u), `${u} not a url: line in the concern archive`);
  for (const id of TARGETS) {
    const before = new Set(urlsOf(was(id)));
    const urls = nonEmpty(urlsOf(card(id)), `${id} sources`, 1);
    assert.ok(urls.includes(CSPI), `${id} does not cite CSPI`);
    if (id !== 'popcorn') assert.ok(urls.includes(NGP), `${id} does not cite the Non-GMO Project FAQ`);
    for (const u of before) assert.ok(urls.includes(u), `${id} dropped source ${u}`);
    for (const u of urls) assert.ok(before.has(u) || archived.has(u), `${id} url not archived: ${u}`);
    assert.ok((card(id).sources || []).length > (was(id).sources || []).length, `${id} no source added`);
  }
});

test('C6 no health claims, first person, em dash, price, calorie talk, brand or owned-fact wording in what the batch adds', () => {
  const BAN = /\b(causes?|prevents?|lowers? (the )?risk|cancer|tumou?rs?|toxic\w*|unsafe|safe|safer|harm\w*|risks?|linked to|hormon\w*|health\w*|neurolog\w*|immun\w*|exposure|doses?|allerg\w*|herbicides?|glyphosate|pesticides?)\b/i;
  // Owned facts (counterCardLint OWNED_FACTS) for cooking_oils: oil extraction, olive grade, animal fat.
  const OWNED = /\b(cold[- ]pressed|expeller|hexane|solvents?|extra[- ]virgin|lard|tallow)\b/i;
  const BRANDS = /\b(Whole Foods|Costco|Kroger|Sprouts|Walmart|Trader Joe|Lean Cuisine|Nature Valley|Monsanto|Bayer|Hawaii|Arctic|Pinkglow)\b/i;
  for (const id of TARGETS) {
    const t = nonEmpty([added(id)], `${id} added text`, 1)[0];
    assert.doesNotMatch(t, BAN, `${id} health or treatment wording`);
    assert.doesNotMatch(t, OWNED, `${id} owned-fact wording (REPEATED_CLAIM)`);
    assert.doesNotMatch(t, /\b(I|me|my)\b/, `${id} first person`);
    assert.doesNotMatch(t, /—/, `${id} em dash`);
    assert.doesNotMatch(t, /\$\s?\d|\bprice\w*|\bcheap\w*|\bcalor\w*|\blogged\b/i, `${id} price or calorie wording`);
    assert.doesNotMatch(t, BRANDS, `${id} brand name`);
  }
});
// Owns the two-line rewrite's text (docs/CARD-STYLE-SAMPLES.md): every card's decision and
// buying_tips (and egg_labels sources) equal the pin in twoLinePin.js, which older batch tests read through.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { nonEmpty } from '../../lib/testGuards.js';
import { TWO_LINE } from './twoLinePin.js';
import { matchItemToCard } from '../../lib/listMatch.js';

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));

test('every card carries the pinned two-line decision and buying_tips', () => {
  const cards = nonEmpty(kb.entries.filter((e) => e.kind !== 'pick'), 'cards', 180);
  for (const e of cards) {
    assert.ok(TWO_LINE[e.id], `${e.id} has no two-line pin`);
    // Every pinned field, so a field the older tests restore (cart_pick, pick_steps) is still checked live.
    for (const [k, v] of Object.entries(TWO_LINE[e.id])) assert.deepEqual(e[k], v, `${e.id}.${k}`);
  }
  assert.equal(Object.keys(TWO_LINE).length, cards.length, 'a pin for a card that is gone');
});

// Known gap: lintSections L5 makes the chuck pick carry the G1 term, and that term alone outscores
// beef_cuts_basics for beef_grassfed_vs_grainfed (scorePool's top-2 window), so the pick lands uncarded.
// Pinned null so a matcher or wording change that fixes it (or sends it to the wrong card) goes red.
const KNOWN_UNCARDED = new Set(['beef_cuts_basics']);
test('every pinned cart_pick resolves to its own card on the live KB', () => {
  const ids = nonEmpty(Object.keys(TWO_LINE).filter((id) => TWO_LINE[id].cart_pick), 'pinned cart picks', 3);
  for (const id of ids) {
    const m = matchItemToCard(kb.entries.find((e) => e.id === id).cart_pick);
    assert.equal(m ? m.slug ?? m.id ?? m.entry?.id : null, KNOWN_UNCARDED.has(id) ? null : id, `${id} cart_pick`);
  }
});
// CA-4b: the other sixteen eggs_dairy cards (docs/CARD-ALIGNMENT-PLAN.md CA-4). Written by the planner; do not edit.
import { beforeCa7 } from './ca7Superseded.js';
import { beforeTwoLine, beforeConcern } from './twoLinePin.js';
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import * as lint from '../../lib/counterCardLint.js';
import { projectEntry, parseReviewTable, sectionForCategory } from '../../lib/counterCards.js';
import { matchItemToCard } from '../../lib/listMatch.js';
import { nonEmpty } from '../../lib/testGuards.js';
import { assertPassRule } from './passRule.js';

const SERVER = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const ROOT = join(SERVER, '..');
const kb = JSON.parse(readFileSync(join(SERVER, 'kristy_perimeter_kb.json'), 'utf8'));
const base = JSON.parse(execFileSync('git', ['show', 'a392e36:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());
const reviewText = readFileSync(join(ROOT, 'docs', 'do-lines-review.md'), 'utf8');
const reviewed = parseReviewTable(reviewText);
const reviewHeadline = id => reviewText.split('\n').find(line => line.startsWith('| `' + id + '` |'))?.split('|')[3].trim();
const doLines = JSON.parse(readFileSync(join(SERVER, 'lib', 'doLines.json'), 'utf8'));
const now = (id) => beforeCa7(beforeTwoLine(kb.entries.find((e) => e.id === id)));
const was = (id) => base.entries.find((e) => e.id === id);
const without = (e, keys) => Object.fromEntries(Object.entries(e ?? {}).filter(([k]) => !keys.includes(k)));
const COPY = ['decision', 'short_answer', 'why', 'detail', 'kristy_take', 'tier_note', 'question', 'buying_tips', 'watch_out', 'pick_steps', 'science', 'instead', 'cart_pick', 'labels_decoded', 'eyebrow_short'];
const leaves = (v) => (typeof v === 'string' ? [v] : Array.isArray(v) ? v.flatMap(leaves) : v && typeof v === 'object' ? Object.values(v).flatMap(leaves) : []);
const copy = (e) => COPY.flatMap((f) => leaves(e?.[f]));
const fresh = (id) => { const old = new Set(copy(was(id))); return copy(now(id)).filter((s) => !old.has(s)); };
const words = (s) => s.trim().split(/\s+/).length;

const SPEC = {
