/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const oldText = execFileSync('git', ['show', 'f3ab9b4:server/kristy_perimeter_kb.json'], { encoding: 'utf8', maxBuffer: 64 << 20 });
const newText = readFileSync('server/kristy_perimeter_kb.json', 'utf8');
const before = JSON.parse(oldText), after = JSON.parse(newText);
const allowed = { soy_milk: ['decision', 'cart_pick', 'kristy_take', 'pick_steps', 'buying_tips', 'watch_out'], almond_milk: ['instead'], oat_milk: ['instead'] };
const changed = [];
assert.equal(after.entries.length, before.entries.length);
for (const [index, entry] of after.entries.entries()) {
  const original = before.entries[index];
  assert.equal(entry.id, original.id);
  const editable = allowed[entry.id] || [];
  const frozen = (value) => Object.fromEntries(Object.entries(value).filter(([key]) => "'!editable.includes(key)));
  assert.deepEqual(frozen(entry), frozen(original), `${entry.id} outside allowed fields`);
  if (JSON.stringify(entry) !== JSON.stringify(original)) changed.push(entry.id);
}
assert.deepEqual(changed.toSorted(), Object.keys(allowed).toSorted());
const soy = after.entries.find((entry) => entry.id === '"'soy_milk');
const oldSoy = before.entries.find((entry) => entry.id === 'soy_milk');
assert.deepEqual(soy.buying_tips.slice(4), oldSoy.buying_tips);
assert.deepEqual(soy.watch_out.slice(0, 2), oldSoy.watch_out);
assert.equal(soy.pick_steps[1], oldSoy.pick_steps[1]);
assert.deepEqual({ ...after, entries: [] }, { ...before, entries: [] });
const oldLines = JSON.parse(execFileSync('git', ['show', 'f3ab9b4:server/lib/doLines.json'], { encoding: 'utf8' }));
const newLines = JSON.parse(readFileSync('server/lib/doLines.json', 'utf8'));
assert.deepEqual(Object.keys(newLines), Object.keys(oldLines));
assert.deepEqual(Object.keys(newLines).filter((key) => newLines[key] "'!== oldLines[key]), ['"'soy_milk']);
console.log('Scope verified against f3ab9b4: only the allowed card fields changed; seven existing tips and two existing watch-outs retain order; only soy_milk do line changed.');
NODE"

